import {lessons} from './lessons.js';
import {defaults} from './motion.js';
export const families=['scale','lead','depth','low','finish','reveal','horizon','orbit'];
export function generateLesson(serial){
 let seed=(serial*2654435761)>>>0;const pick=values=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return values[Math.floor(seed/4294967296*values.length)];};
 const type=families[(serial-1)%families.length],base=lessons.find(l=>l.id===type)||lessons[4];
 const l=structuredClone(base);l.id='generated-'+serial;l.type=type;l.criteria={};l.initial={...defaults(),walk:false};l.example={...defaults(),walk:false};
 const duration=pick([4,5,6,8,10]);l.initial.duration=duration;l.example.duration=duration;
 if(type==='scale'){const focal=pick([24,28,35,40]),start=pick([12,14,16]),end=focal/35*4.2;l.example={...l.example,focal,start:{x:pick([-1,0,1]),y:1.6,z:start},end:{x:0,y:1.6,z:end}};l.criteria.endMin=pick([.35,.4,.45]);l.title='풍경 → 인물 접근';l.goal=`처음에는 인물 높이가 화면의 30% 이하인 풍경 구도, 끝에는 ${Math.round(l.criteria.endMin*100)}~85%인 인물 구도를 만드세요. 크기가 1.4배 이상 커지게 하고 전신을 유지하세요.`;}
 if(type==='lead'){const direction=pick([-1,1]),focal=pick([24,35,50]),z=focal/35*6;l.example={...l.example,walk:true,walkDirection:direction,focal,frameX:-direction*pick([.3,.35,.4]),start:{x:-direction,y:1.6,z},end:{x:direction,y:1.6,z}};l.initial.walk=true;l.initial.walkDirection=direction;l.title='걷는 방향과 여백';l.goal=`인물이 ${direction===1?'왼쪽 → 오른쪽':'오른쪽 → 왼쪽'}으로 걷습니다. 진행 방향 앞쪽에 반대쪽보다 최소 8%p 더 넓은 여백을 남기고, 전체 경로의 80% 이상에서 유지하세요.`;}
 if(type==='depth'){const z=pick([10,11,12]);l.example={...l.example,start:{x:-5,y:1.6,z},end:{x:0,y:1.6,z},focal:24};l.title='전경과 배경의 상대 이동';l.goal='가까운 바위 또는 나무를 넣고 옆으로 이동하세요. 시작·끝에 공통으로 보이는 전경이 먼 건물에 비해 화면 너비의 5%p 이상 다르게 움직이도록 설계하세요.';}
 if(type==='low'){const maxHeight=pick([.5,.6,.8]);l.criteria.maxHeight=maxHeight;l.example={...l.example,start:{x:pick([-1,0,1]),y:maxHeight,z:6},end:{x:0,y:maxHeight,z:5},focal:pick([24,28])};l.title='낮은 시점과 주변 공간';l.goal=`경로 전체의 카메라 높이를 ${maxHeight.toFixed(1)}m 이하로 유지하고, 종료 시 인물 높이를 화면의 15~65%로 만드세요. 전신과 주변 공간을 함께 보여주세요.`;}
 if(type==='finish'){l.title='무빙 마지막 프레임';const focal=pick([35,40,50]);l.criteria.endMin=pick([.35,.4,.45]);l.example={...l.example,focal,start:{x:0,y:1.6,z:10},end:{x:0,y:1.6,z:focal/35*4}};l.goal=`Dolly 또는 Orbit으로 1m 이상 이동하고 마지막 인물 높이를 ${Math.round(l.criteria.endMin*100)}~85%로 만드세요. 이동 전체에서 전신과 얼굴·몸통의 시야를 유지하세요.`;}
 if(type==='reveal'){l.title='바위 뒤에서 인물 드러내기';l.example={...l.example,start:{x:-12,y:1.1,z:6},end:{x:pick([-7,-6,-5]),y:1.1,z:pick([9,10])},focal:35};l.initial={...l.example,end:{x:-12,y:1.1,z:6}};l.goal='시작에는 가까운 바위로 인물의 머리 또는 몸통을 가리고, 이동 끝에서는 인물을 드러내세요. 마지막 20% 구간은 인물이 가리지 않고 전신이 프레임 안에 있어야 합니다.';l.tip='왼쪽 바위와 인물이 일직선이 되는 시작점에서 출발한 뒤 옆으로 빠져 보세요. 시작의 가림은 이번 문제의 의도입니다.';l.why='전경의 가림으로 시선을 지연한 뒤 옆으로 이동해 인물을 드러냅니다. 시작 가림을 무조건 감점하지 않고 종료의 시야 확보를 평가합니다.';}
 if(type==='horizon'){const sky=pick([true,false]);l.criteria.horizonMin=sky?.52:.18;l.criteria.horizonMax=sky?.78:.48;l.title=sky?'하늘에 공간 주기':'해변 지면에 공간 주기';l.example={...l.example,start:{x:0,y:sky?.5:1.8,z:7},end:{x:0,y:sky?.5:1.8,z:6},focal:24,aimY:sky?1.4:.6};l.initial={...defaults(),walk:false};l.goal=`${sky?'하늘':'해변 지면'}을 강조하도록 수평선을 화면 위에서 ${Math.round(l.criteria.horizonMin*100)}~${Math.round(l.criteria.horizonMax*100)}% 영역에 배치하세요. 인물 전신을 유지하며 시작·끝에서 이 위치를 확보하세요.`;l.tip='카메라 높이와 바라보는 높이는 다릅니다. 높이를 바꾼 뒤 추적의 바라보는 높이 또는 수동 Tilt로 수평선을 조절해 보세요.';l.why=sky?'낮은 카메라에서 조금 올려다보며 하늘 영역을 넓힙니다.':'높은 카메라에서 내려다보며 지면과 해변의 정보를 넓힙니다.';}
 if(type==='orbit'){const arc=pick([-65,-45,45,65]),focal=pick([35,40]);l.criteria.minArc=Math.abs(arc)-5;l.example={...l.example,mode:'orbit',arc,focal,start:{x:0,y:1.6,z:5},end:{x:0,y:1.6,z:5}};l.title='인물 크기를 유지하는 Orbit';l.goal=`인물 주위를 ${l.criteria.minArc}° 이상 Orbit으로 회전하세요. 시작·끝 인물 크기 차이를 20% 이내로 유지하고, 인물 높이를 화면의 30~85%로 확보하세요. 이동 중 가림과 잘림을 피하세요.`;l.tip='반경을 일정하게 유지하는 Orbit으로 시작하고, 인물 크기는 반경과 화각으로 조절하세요.';l.why='피사체와 거리를 유지하며 배경의 위치를 바꿉니다. 여기서는 인물 크기의 유지가 목표이므로 Dolly 접근과 평가 기준이 다릅니다.';}
 l.title=`새 문제 ${serial} · ${l.title}`;l.goal+=` 촬영 길이 ${duration}초를 기준으로 확인하세요.`;return l;
}
